fragments._should_penalize_stream_error:
def _should_penalize_stream_error(code: str | None) -> bool:
    if code is None:
        return False
    return code in _facade()._ACCOUNT_RECOVERY_RETRY_CODES or code in _facade()._TRANSIENT_RETRY_CODES

fragments._rewrite_previous_response_stream_error:
def _rewrite_previous_response_stream_error(*, previous_response_id: str | None, preferred_account_id: str | None, error_code: str | None, error_type: str | None, error_message: str | None, error_param: str | None) -> tuple[str, str, str | None] | None:
    if previous_response_id is None:
        return None
    if _facade()._is_previous_response_not_found_error(code=error_code, param=error_param, message=error_message):
        _record_continuity_fail_closed(surface='http_stream', reason='previous_response_not_found', previous_response_id=previous_response_id, upstream_error_code=error_code)
        return ('stream_incomplete', PREVIOUS_RESPONSE_STREAM_INCOMPLETE_MESSAGE, None)
    if _facade()._is_missing_tool_output_error(code=error_code, param=error_param, message=error_message):
        _record_continuity_fail_closed(surface='http_stream', reason='missing_tool_output', previous_response_id=previous_response_id, upstream_error_code=error_code)
        return ('stream_incomplete', PREVIOUS_RESPONSE_STREAM_INCOMPLETE_MESSAGE, None)
    normalized_code = _normalize_error_code(error_code, error_type)
    if preferred_account_id is not None and normalized_code in _facade()._ACCOUNT_RECOVERY_RETRY_CODES:
        _record_continuity_fail_closed(surface='http_stream', reason='owner_account_unavailable', previous_response_id=previous_response_id, upstream_error_code=normalized_code)
        return ('previous_response_owner_unavailable', 'Previous response owner account is unavailable; retry later.', normalized_code)
    return None
